es":50708,"checkedAt":"2026-11-01T14:20:29.712Z","fact":"Exact ISBN block image + human visual title/author review, sheet5"}]}},{"relation":"catalog_work_descriptions","ref":"description:76","key":{"work_id":977100052,"language":"nl"},"before":null,"after":{"work_id":977100052,"language":"nl","bound_author_id":977300026,"text":"Geneticus Don Tillman zoekt een levenspartner en probeert die zoektocht met een uitgebreide vragenlijst overzichtelijk te maken. Zijn plan werkt anders uit wanneer Rosie Jarman verschijnt, die niet aan zijn voorwaarden voldoet. Rosie zoekt haar biologische vader en kan Dons kennis gebruiken. Hun gezamenlijke onderzoek brengt hem in situaties die hij niet vooraf kan organiseren. Zo moet hij opnieuw nadenken over de eigenschappen die werkelijk van belang zijn in een relatie.","source_type":"official_catalog","source_name":"Bureau ISBN; oorspronkelijke gecontroleerde samenvatting","source_url":"https://metadata.isbn.nl/28744/het-rosie-project.html","provenance":"original_source_reviewed_summary","review_status":"approved","reviewed_at":"2026-11-01T14:24:00Z","review_batch":"nl006-reviewed-batch-06-20261101","evidence":[{"url":"https://metadata.isbn.nl/28744/het-rosie-project.html","sha256":"590e9801a0f069bf35472dee10312df4fa4e7d85d773a63fe5dfba8010edfe87","checkedAt":"2026-11-01T14:06:31.779Z","fact":"Paperback ISBN 9789021024653 verschijningsdatum 16/01/2020 NUR 302 Vertaalde literaire roman, novelle imprint Luitingh Sijthoff uitgever Luitingh-Sijthoff B.V., Uitgeverij taal Nederlands","sourceAuthors":"Graeme Simsion","identityNote":"Same canonical Work, translation attached to existing identity; no author/Work merge."}]}},{"relation":"editions","ref":"edition:9789044360240","key":{"id":977200140},"before":null,"after":{"work_id":977100053,"title":"Zoen me tot ik zwicht","language":"nld","isbn_13":"9789044360240","isbn_10":null,"open_library_edition_id":null,"publisher":"Overamstel Uitgevers","id":977200140}},{"relation":"catalog_edition_metada