n.html","provenance":"original_source_reviewed_summary","review_status":"approved","reviewed_at":"2026-11-01T14:24:00Z","review_batch":"nl006-reviewed-batch-06-20261101","evidence":[{"url":"https://metadata.isbn.nl/128673/ons-feilbare-denken.html","sha256":"6ec878b7d0630244d24f3d1e78e1666bf6e0a78f444ed0845ee3bd499b2735c8","checkedAt":"2026-11-01T14:04:06.965Z","fact":"Paperback ISBN 9789047009009 verschijningsdatum 15/01/2016 NUR 770 Psychologie algemeen imprint Business Contact uitgever Atlas Contact, Uitgeverij taal Nederlands","sourceAuthors":"Daniel Kahneman","identityNote":"Same canonical Work, translation attached to existing identity; no author/Work merge."}]}}]'::jsonb;receipt jsonb;r jsonb;p jsonb;k jsonb;expected jsonb;prior jsonb;ids jsonb:='{}';kv record;i integer:=0;n integer;begin
